package android.os;public class HandlerThread extends Thread{private Looper looper;public HandlerThread(String n){super(n);setDaemon(true);}public HandlerThread(String n,int p){this(n);}public void run(){synchronized(this){looper=new Looper(this);notifyAll();}looper.loop();}public synchronized Looper getLooper(){while(looper==null&&isAlive())try{wait();}catch(InterruptedException e){Thread.currentThread().interrupt();return null;}return looper;}public boolean quitSafely(){return quit();}public boolean quit(){Looper l=getLooper();if(l!=null){l.quit=true;interrupt();}return true;}}

